# Obtener todos los gateways de WhatsApp gateways = env['mail.gateway'].search([('gateway_type', '=', 'whatsapp')])
if not gateways: raise UserError('No se encontraron gateways de WhatsApp configurados. Por favor, configure al menos un gateway antes de cargar las plantillas.')
created_count = 0 updated_count = 0
for gateway in gateways: # Primera pasada: crear todas las plantillas for template_data in templates_data: # Buscar si ya existe existing = env['mail.whatsapp.template'].search([ ('name', '=', template_data['name']), ('gateway_id', '=', gateway.id), ('language', '=', template_data['language']), ], limit=1)
# Preparar datos de la plantilla template_vals = { 'name': template_data['name'], 'body': template_data['body'], 'category': template_data['category'], 'language': template_data['language'], 'model_id': template_data['model_id'], 'gateway_id': gateway.id, 'state': 'draft', }
if existing: # Actualizar plantilla existente existing.write(template_vals) template = existing updated_count += 1 else: # Crear nueva plantilla template = env['mail.whatsapp.template'].create(template_vals) created_count += 1
# Mostrar resultado message = 'Plantillas cargadas correctamente:
